		return 1;
	}

	uint16_t itemId;
	if (Lua::isNumber(L, 2)) {
		itemId = Lua::getNumber<uint16_t>(L, 2);
	} else {
		itemId = Item::items.getItemIdByName(Lua::getString(L, 2));
		if (itemId == 0) {
			lua_pushnil(L);
			return 1;
		}
	}
	const auto subType = Lua::getNumber<int32_t>(L, 3, -1);

	const auto &item = g_game().findItemOfType(tile, itemId, false, subType);
	if (item) {
