void KVFunctions::pushValueWrapper(lua_State* L, const ValueWrapper &valueWrapper) {
	std::visit(
		[L](const auto &arg) {
			using T = std::decay_t<decltype(arg)>;
			if constexpr (std::is_same_v<T, StringType>) {
				pushStringValue(L, arg);
			} else if constexpr (std::is_same_v<T, BooleanType>) {
				Lua::pushBoolean(L, arg);
			} else if constexpr (std::is_same_v<T, IntType>) {
				pushIntValue(L, arg);
			} else if constexpr (std::is_same_v<T, DoubleType>) {
				pushDoubleValue(L, arg);
			} else if constexpr (std::is_same_v<T, ArrayType>) {
				pushArrayValue(L, arg);
			} else if constexpr (std::is_same_v<T, MapType>) {
				pushMapValue(L, arg);
			}
		},
		valueWrapper.getVariant()
	);
}

void Lua::pushOutfit(lua_State* L, const Outfit_t &outfit) {
	if (validateDispatcherContext(__FUNCTION__)) {
		return;
	}

	lua_createtable(L, 0, 17);
	setField(L, "lookType", outfit.lookType);
	setField(L, "lookTypeEx", outfit.lookTypeEx);
	setField(L, "lookHead", outfit.lookHead);
	setField(L, "lookBody", outfit.lookBody);
	setField(L, "lookLegs", outfit.lookLegs);
	setField(L, "lookFeet", outfit.lookFeet);
	setField(L, "lookAddons", outfit.lookAddons);
	setField(L, "lookMount", outfit.lookMount);
	setField(L, "lookMountHead", outfit.lookMountHead);
	setField(L, "lookMountBody", outfit.lookMountBody);
	setField(L, "lookMountLegs", outfit.lookMountLegs);
	setField(L, "lookMountFeet", outfit.lookMountFeet);
	setField(L, "lookFamiliarsType", outfit.lookFamiliarsType);
	setField(L, "lookWing ", outfit.lookWing);
	setField(L, "lookAura", outfit.lookAura);
	setField(L, "lookEffect ", outfit.lookEffect);
	setField(L, "lookShader ", outfit.lookShader);
}

void Lua::pushPosition(lua_State* L, const Position &position, int32_t stackpos /* = 0*/) {
	if (validateDispatcherContext(__FUNCTION__)) {
		return;
	}

	lua_createtable(L, 0, 4);

	setField(L, "x", position.x);
	setField(L, "y", position.y);
	setField(L, "z", position.z);
	setField(L, "stackpos", stackpos);

	setMetatable(L, -1, "Position");
}

int ContainerFunctions::luaContainerGetEmptySlots(lua_State* L) {
	// container:getEmptySlots([recursive = false])
	const auto &container = Lua::getUserdataShared<Container>(L, 1, "Container");
	if (!container) {
		lua_pushnil(L);
		return 1;
	}

	uint32_t slots = container->capacity() - container->size();
	const bool recursive = Lua::getBoolean(L, 2, false);
	if (recursive) {
		for (ContainerIterator it = container->iterator(); it.hasNext(); it.advance()) {
			if (const auto &tmpContainer = (*it)->getContainer()) {
				slots += tmpContainer->capacity() - tmpContainer->size();
			}
		}
	}
	lua_pushnumber(L, slots);
	return 1;
}

