int ModalWindowFunctions::luaModalWindowGetId(lua_State* L) {
	// modalWindow:getId()
	const auto &window = Lua::getUserdataShared<ModalWindow>(L, 1, "ModalWindow");
	if (window) {
		lua_pushnumber(L, window->id);
	} else {
